import limited_client as robot, numpy as np
from PIL import Image
try:
 import scipy; print('scipy',scipy.__version__)
except Exception as e: print('no scipy',e)
o=robot.observe(camera=2); Image.fromarray(o['rgb']).save('/app/output/overhead.png')
r=o['rgb'].astype(int); d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']
print('STATUS',robot.status()); print('ROBOT',o['robot'])
# connected components via scipy ndimage if available
try:
 from scipy import ndimage
 masks={
 'blue':(r[:,:,2]>100)&(r[:,:,2]>r[:,:,0]*1.35)&(r[:,:,2]>r[:,:,1]*1.15),
 'green':(r[:,:,1]>r[:,:,0]*1.25)&(r[:,:,1]>r[:,:,2]*1.2)&(r[:,:,1]>70),
 'brown':(r[:,:,0]>r[:,:,2]*1.35)&(r[:,:,0]>r[:,:,1]*1.05)&(r[:,:,0]<180)&(r[:,:,1]<130)}
 for name,m in masks.items():
  lab,n=ndimage.label(m); objs=ndimage.find_objects(lab); comps=[]
  for i,s in enumerate(objs,1):
   if s is None: continue
   area=int((lab[s]==i).sum())
   if area>25: comps.append((area,(s[1].start,s[0].start,s[1].stop-1,s[0].stop-1)))
  print(name,sorted(comps,reverse=True)[:20])
except Exception as e: print('component error',e)
def world(u,v):
 z=float(np.median(d[max(0,v-2):v+3,max(0,u-2):u+3])); p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]); return round(z,4),np.round((T@p)[:3],4)
for label,u,v in [('carton_back',277,218),('carton_front',273,285),('bottle',211,286),('can',239,269),('brown_mat',117,260),('blue_tray',369,286),('table',400,400)]: print(label,world(u,v))
